/* Aggregated census exposure only. No individual data or mobility tracking. */
window.FloodExposure={cache:new Map(),async calculate(parish,scenario,period){let key=parish.properties.dtmnfr+':'+period;if(this.cache.has(key))return this.cache.get(key);let task=(async()=>{let box=turf.bbox(parish),base='https://services.arcgis.com/CCZiGSEQbAxxFVh3/ArcGIS/rest/services/BGRI_Censos_2021/FeatureServer/3/query',all=[];for(let offset=0;;){let q=new URLSearchParams({f:'geojson',where:'1=1',geometry:box.join(','),geometryType:'esriGeometryEnvelope',inSR:'4326',outSR:'4326',spatialRel:'esriSpatialRelIntersects',outFields:'BGRI2021,DTMNFR21,N_INDIVIDUOS,N_INDIVIDUOS_0_14,N_INDIVIDUOS_65_OU_MAIS',resultRecordCount:'1000',resultOffset:String(offset),orderByFields:'OBJECTID',returnGeometry:'true'});let r=await fetch(base+'?'+q,{signal:AbortSignal.timeout(45000)});if(!r.ok)throw Error('HTTP '+r.status);let j=await r.json();if(j.error||!j.features)throw Error(j.error?.message||'Resposta BGRI inválida');all.push(...j.features);if(!j.exceededTransferLimit&&j.features.length<1000)break;if(!j.features.length)break;offset+=j.features.length;if(offset>50000)throw Error('Área demasiado extensa para análise no navegador');}
let masks=[];for(let sf of scenario.features){let b=turf.bbox(sf);if(box[0]>b[2]||box[2]<b[0]||box[1]>b[3]||box[3]<b[1])continue;let clip=turf.intersect(turf.featureCollection([parish,sf]));if(clip)masks.push(clip);}let mask=masks.length===1?masks[0]:masks.length?turf.union(turf.featureCollection(masks)):null;let totals={residents:0,children:0,elderly:0,exposed:0,exposed_children:0,exposed_elderly:0,subsections:0,missing:0,period,source:base,method:'area_weighted_uniform_population',computed_at:new Date().toISOString(),coverage:!!mask};
for(let unit of all){let a=turf.area(unit);if(a<=0)continue;let clip=turf.intersect(turf.featureCollection([parish,unit]));if(!clip)continue;let ratio=Math.min(1,turf.area(clip)/a),exp=mask?turf.intersect(turf.featureCollection([mask,clip])):null,er=exp?Math.min(ratio,turf.area(exp)/a):0,p=unit.properties;totals.subsections++;for(let [field,total,exposed] of [['N_INDIVIDUOS','residents','exposed'],['N_INDIVIDUOS_0_14','children','exposed_children'],['N_INDIVIDUOS_65_OU_MAIS','elderly','exposed_elderly']]){if(!Number.isFinite(p[field])||p[field]<0){totals.missing++;continue;}totals[total]+=ratio*p[field];totals[exposed]+=er*p[field];}}
if(totals.missing)throw Error('Há contagens censitárias em falta; cálculo incompleto não publicado');return totals;})();this.cache.set(key,task);try{return await task;}catch(e){this.cache.delete(key);throw e;}}};
